import{_ as i,o as t,a as o,b as l}from"./app.DKoEZOcr.js";const r="/ascendc.github.io/pr/5487/assets/operator_implementation_components.D2_Q1hQV.png",a="/ascendc.github.io/pr/5487/assets/vector_tiling_intro.CTEzt0H7.png",T=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矢量编程","link":"/guide/operator_practice/simd_operator_impl/vector_programming/vector_programming"},{"text":"多核Tiling切分","link":"/guide/operator_practice/simd_operator_impl/vector_programming/multi_core_tiling/overview"},{"text":"概述","link":"/guide/operator_practice/simd_operator_impl/vector_programming/multi_core_tiling/overview"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/vector_programming/multi_core_tiling/overview.md","filePath":"guide/operator_practice/simd_operator_impl/vector_programming/multi_core_tiling/overview.md","lastUpdated":1787050286000}'),n={name:"guide/operator_practice/simd_operator_impl/vector_programming/multi_core_tiling/overview.md"};function c(p,e,_,s,g,m){return t(),o("div",null,[...e[0]||(e[0]=[l('<div><article class="markdown-body"><h1>概述</h1><p>Ascend C核函数（Kernel）是在Device侧执行的并行函数。为了提高算子的执行效率，通常采用多核并行计算，将输入数据切分后分配到不同的逻辑核上处理；同时，由于单个核的Local Memory容量有限，无法一次完整容纳算子的输入和输出数据，需要分批搬运数据进行计算。这种对输入数据进行切分、分块计算的过程称为<strong>Tiling</strong>。</p><p>切分数据的算法称为Tiling算法或Tiling策略；根据算子shape等信息计算切分相关参数（如每次搬运的块大小、循环次数等）的程序，称为<strong>Tiling实现</strong>，也叫Tiling函数（Tiling Function）。<a href="../basic_vector_operator.html">基础矢量算子</a>与<a href="../tbuf_usage.html">TBuf的使用</a>样例均在单核上运行，不涉及Host侧Tiling实现。</p><p>由于Tiling实现完成的均为标量计算，而AI Core并不擅长这类计算，因此通常将其独立出来由Host侧执行；对于动态shape算子，切分参数无法在编译期确定，也需要在Host侧计算。</p><p>开发者需要分析并设计Tiling参数、定义Tiling结构体，在Host侧通过上下文获取输入输出shape信息，根据shape信息计算Tiling参数并设置到对应的Tiling结构体中；随后通过核函数（Kernel）入口参数将Tiling信息传入核函数（Kernel）。核函数（Kernel）内部解析Host侧传入的Tiling结构体，根据Tiling信息控制数据搬入、搬出Local Memory的流程，并完成计算逻辑。</p><p><strong>图 1</strong> 算子实现组成</p><p><img src="'+r+'" alt="算子实现组成" title="算子实现组成"></p><p>如上图所示，算子实现由Device侧的核函数（Kernel）实现与Host侧的Tiling实现两部分组成：核函数（Kernel）实现负责在Device侧完成数据搬运、矢量计算、内存管理和任务同步等逻辑；Tiling实现用于在核函数（Kernel）执行前，根据输入shape等信息在Host侧计算核函数（Kernel）所需的切分参数。对于输入和输出shape固定、切分策略固定的简单算子，Host侧Tiling实现可以省略；对于动态shape或多核并行场景，每个核处理的数据量、核内分块数量等参数通常需要在Host侧计算后传递给核函数（Kernel）使用。</p><p>对输入数据进行切分时应遵循以下原则：</p><ol><li><p>以DataBlock为最小切分单位。受硬件限制，进行Unified Buffer（UB）相关的数据搬运和矢量计算时，搬运的数据长度和操作数的起始地址都需要保证32字节对齐，即以DataBlock为单位进行操作，一个DataBlock大小为32字节；输入数据不满足DataBlock大小对齐要求时，需按DataBlock大小向上对齐。</p></li><li><p>充分利用UB空间。AI Core与外部存储交互时会产生性能开销，频繁地进行数据搬运会导致性能瓶颈，因此应尽可能充分利用UB空间，减少从Global Memory搬运数据的次数。</p></li><li><p>均衡利用多核计算能力。AI处理器包含多个AI Core，应将计算均衡分配到各核上，充分发挥多核并行优势。</p></li></ol><p>本章基于<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/02_features/02_tiling_selector/vector_tiling_strategy/README.md">矢量计算多核Tiling切分策略样例</a>，以两个一维Tensor相加的Add矢量算子为例，对多核Tiling切分的典型场景进行说明。样例实现文件为<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/02_features/02_tiling_selector/vector_tiling_strategy/vector_tiling_strategy.asc">vector_tiling_strategy.asc</a>。</p><p><strong>图 2</strong> 多核Tiling示意图<span id="fig-2"></span></p><p><img src="'+a+'" alt="多核Tiling示意图" title="多核Tiling示意图"></p><p>如上图所示，将长度为<code>totalLength</code>的算子输入分配到多个核上进行计算。Host侧Tiling先将输入数据量按DataBlock对齐，再按主块长度<code>mainTileLength</code>在各核上分配相同数量的主块，随后把剩余数据以DataBlock为最小单位尽量均衡地分配到各核。当剩余数据能均分到每个核时，各核处理的数据量相同；无法均分时，各核处理的数据量分为两类——处理数据量较多的整核和处理数据量较少的尾核，其中整核数量记为<code>formerNum</code>。对于单个核的计算数据，核内先处理<code>tileNum</code>个长度为<code>mainTileLength</code>的主块；如果最后剩余的数据长度不足一个主块，则通过<code>lastTileLength</code>记录尾块长度。Tiling切分完成后，上述参数被封装到Tiling结构体并通过核函数（Kernel）入口传入核函数（Kernel）侧；核函数（Kernel）侧根据<code>GetBlockIdx()</code>和Tiling参数计算当前核需处理的输入数据的Global Memory偏移，并按<code>tileNum</code>和<code>lastTileLength</code>循环完成数据搬入、计算和搬出。</p><p>本章涉及如下概念：</p><ul><li>主块：基于Local Memory可用空间确定的单个核一次处理的最大数据块。主块长度使用<code>mainTileLength</code>表示，且需要按32字节对齐。</li><li>尾块：单个核内最后一个长度小于<code>mainTileLength</code>的数据块。尾块长度使用<code>lastTileLength</code>表示。</li><li>整核：核间数据无法完全均分时，处理数据量较多的核。</li><li>尾核：核间数据无法完全均分时，处理数据量较少的核。</li></ul><p>根据数据切分的情况，有如下几种场景：</p><ol><li><a href="main_block_even_split.html">主块均分</a>：输入数据可以按参与计算的核数和主块长度均匀切分。完成主块分配后没有剩余数据，各核处理的数据量相同，且核内只包含主块。</li><li><a href="tail_block_even_split.html">尾块均分</a>：完成主块分配后仍有剩余数据，但剩余数据能以DataBlock为最小单位均匀分配到每个核。各核处理的数据量相同，核内除主块外还存在等长尾块。</li><li><a href="tail_core_split.html">尾核切分</a>：完成主块分配后仍有剩余数据，但剩余数据不足以为每个核各分配一个DataBlock，只能以DataBlock为最小单位分配给部分核。获得额外DataBlock的核为整核，其余为尾核；尾核内只包含主块。</li><li><a href="tail_core_tail_block_split.html">尾核尾块切分</a>：完成主块分配后仍有剩余数据，每个核都能分配到若干DataBlock，但仍有少量DataBlock只能分配给部分核。此时既存在处理数据量更多的整核，尾核也需要处理尾块。</li></ol></article></div>',1)])])}const h=i(n,[["render",c]]);export{T as __pageData,h as default};
